#!/usr/bin/python3
"""Tests for the honey-voice lane's Flying Fox unit and installer (generated by agents-bots-honey.org). No root, no OpenRC, no network: the unit is
sourced under sh with stubbed OpenRC functions, and the installer runs against staging directories (HONEY_VOICE_INITD_DIR, HONEY_VOICE_CONFD_DIR).
The one test that runs the installer without a staging directory is skipped for root."""
import os, re, shutil, stat, subprocess, tempfile, unittest

HERE = os.path.dirname(os.path.abspath(__file__))
LANE = next(os.path.abspath(p) for p in (os.path.join(HERE, '..'), HERE) if os.path.isfile(os.path.join(p, 'openrc', 'honey-voice-fox')))
FOX = os.path.join(LANE, 'openrc', 'honey-voice-fox')
BADGER = os.path.join(LANE, 'openrc', 'honey-voice')
INSTALL = os.path.join(LANE, 'openrc', 'honey-voice-install')
FOX_TEMPLATE = os.path.join(LANE, 'honey-voice-fox.conf.template')
LINT = next((c for c in (os.path.join(LANE, '..', '..', '..', 'bin', 'honey-initd-lint'),) if os.path.isfile(c)), None)


def rd(p):
    with open(p) as fh:
        return fh.read()


def wr(p, t):
    with open(p, 'w') as fh:
        fh.write(t)


CONF = {'honey_voice_user': 'vu', 'honey_voice_group': 'vg', 'honey_voice_engine_root': '/srv/engine', 'honey_voice_fox_home': '/srv/agent', 'honey_voice_fox_read_as': 'ra'}


def render(conf=CONF, unit=FOX):
    """Source the unit under sh with the OpenRC helpers stubbed, then print what it set and what its hooks do."""
    sets = '\n'.join('%s=%s' % (k, v) for k, v in conf.items())
    script = '''RC_SVCNAME=honey-voice-fox
%s
getent() { echo "vu:x:1:1::/srv/vu:/bin/sh"; }
checkpath() { echo "checkpath $*"; }
use() { echo "use $*"; }
after() { echo "after $*"; }
ebegin() { :; }
eend() { :; }
. %s
for v in name description command command_args command_user command_background pidfile output_log error_log directory HOME HONEY_FOX_HOME HONEY_FOX_READ_AS PYTHONUNBUFFERED; do eval "echo \\"\\$v=\\$$v\\""; done
echo "PATHTAIL=${PATH##*:}"
depend; start_pre
''' % (sets, unit)
    return subprocess.run(['sh', '-c', script], capture_output=True, text=True, timeout=30, env={'PATH': '/usr/bin:/bin'})


def values(p):
    return dict(l.split('=', 1) for l in p.stdout.splitlines() if re.match(r'^[A-Za-z_]+=', l))


class FoxUnit(unittest.TestCase):
    def test_every_account_and_path_comes_from_conf_d(self):
        p = render(); self.assertEqual(p.returncode, 0, p.stderr); v = values(p)
        self.assertEqual(v['command_args'], '/srv/engine/bin/codex_rollout_watcher.py')
        self.assertEqual(v['command_user'], 'vu:vg'); self.assertEqual(v['directory'], '/srv/vu'); self.assertEqual(v['HOME'], '/srv/vu')
        self.assertEqual(v['PATHTAIL'], '/srv/vu/.local/bin')
        self.assertEqual((v['HONEY_FOX_HOME'], v['HONEY_FOX_READ_AS']), ('/srv/agent', 'ra'))

    def test_the_service_identity_is_unchanged(self):
        v = values(render())
        self.assertEqual((v['name'], v['command'], v['command_background'], v['PYTHONUNBUFFERED']), ('honey-voice-fox', '/usr/bin/python3', 'true', '1'))
        self.assertEqual((v['pidfile'], v['output_log'], v['error_log']), ('/run/honey-voice-fox.pid',) + ('/var/log/honey-voice-fox.log',) * 2)

    def test_hooks_do_what_the_hand_written_unit_did(self):
        out = render().stdout
        self.assertIn('use net dns', out); self.assertIn('after net honey-codex', out)
        self.assertIn('checkpath -f -m 0640 -o vu:vg /var/log/honey-voice-fox.log', out)

    def test_the_group_defaults_to_the_user(self):
        c = dict(CONF); del c['honey_voice_group']; v = values(render(c)); self.assertEqual(v['command_user'], 'vu:vu')

    def test_every_required_variable_is_demanded_by_name(self):
        for var in ('honey_voice_user', 'honey_voice_engine_root', 'honey_voice_fox_home', 'honey_voice_fox_read_as'):
            with self.subTest(var=var):
                c = dict(CONF); del c[var]; p = render(c)
                self.assertNotEqual(p.returncode, 0); self.assertIn(var, p.stderr)

    def test_no_account_name_or_home_path_is_written_in_the_unit(self):
        text = rd(FOX)
        for needle in ('/home/', 'gille', 'agent-codex', 'metsatron', '/root'):
            self.assertNotIn(needle, text, needle)

    def test_it_has_a_stop_of_its_own_and_the_lint_passes_it(self):
        self.assertRegex(rd(FOX), r'(?m)^stop\(\) \{')
        if not LINT: self.skipTest('SKIPPED: the lint is not beside this lane')
        p = subprocess.run(['python3', '-I', LINT, '--confd', '/nonexistent', FOX], capture_output=True, text=True)
        self.assertEqual(p.returncode, 0, p.stdout)

    def test_the_conf_template_names_exactly_the_variables_the_unit_requires(self):
        names = set(re.findall(r'(?m)^(honey_voice_[a-z_]+)=', rd(FOX_TEMPLATE)))
        used = set(re.findall(r'\$\{(honey_voice_[a-z_]+)[:}]', rd(FOX)))
        self.assertEqual(names, used)

    def test_the_template_is_not_filled_in(self):
        for l in rd(FOX_TEMPLATE).splitlines():
            if re.match(r'^honey_voice_', l): self.assertTrue(l.endswith('='), l)


class Installer(unittest.TestCase):
    def setUp(self):
        self.d = tempfile.mkdtemp(prefix='hvl-'); self.addCleanup(shutil.rmtree, self.d, True)
        self.lane = os.path.join(self.d, 'lane')
        for sub in ('openrc', 'bin'): os.makedirs(os.path.join(self.lane, sub))
        shutil.copy(INSTALL, os.path.join(self.lane, 'openrc', 'honey-voice-install'))
        for name in ('honey-voice', 'honey-voice-fox'): shutil.copy(os.path.join(LANE, 'openrc', name), os.path.join(self.lane, 'openrc', name))
        wr(os.path.join(self.lane, 'bin', 'provider-rollout-watcher.py'), 'print("w")\n')
        self.engine = os.path.join(self.d, 'engine'); os.makedirs(os.path.join(self.engine, 'bin'))
        self.initd = os.path.join(self.d, 'init.d'); self.confd = os.path.join(self.d, 'conf.d')
        os.makedirs(self.initd); os.makedirs(self.confd)

    def conf(self, *svcs):
        for s in svcs or ('honey-voice-badger', 'honey-voice-fox'): wr(os.path.join(self.confd, s), 'x=1\n')

    def run_(self, *args, staging=True):
        env = dict(os.environ, HONEY_VOICE_ENGINE_ROOT=self.engine, HONEY_VOICE_CONFD_DIR=self.confd)
        env.pop('HONEY_VOICE_INITD_DIR', None)
        if staging: env['HONEY_VOICE_INITD_DIR'] = self.initd
        return subprocess.run(['bash', os.path.join(self.lane, 'openrc', 'honey-voice-install'), *args], capture_output=True, text=True, env=env, timeout=60)

    def test_install_without_conf_d_refuses_and_writes_nothing(self):
        p = self.run_('install'); self.assertEqual(p.returncode, 1)
        self.assertIn('conf.d missing', p.stderr); self.assertIn('nothing was written', p.stderr)
        self.assertEqual(os.listdir(self.initd), []); self.assertEqual(os.listdir(os.path.join(self.engine, 'bin')), [])

    def test_one_missing_conf_d_is_enough_to_refuse(self):
        self.conf('honey-voice-badger'); p = self.run_('install'); self.assertEqual(p.returncode, 1); self.assertIn('honey-voice-fox', p.stderr); self.assertEqual(os.listdir(self.initd), [])

    def test_a_dry_run_install_without_conf_d_also_refuses(self):
        self.assertEqual(self.run_('--dry-run', 'install').returncode, 1)

    def test_check_reports_the_missing_conf_d_and_exits_1(self):
        p = self.run_('check'); self.assertEqual(p.returncode, 1); self.assertIn('conf.d missing', p.stderr); self.assertIn('drift', p.stdout)

    def test_install_places_both_units_with_mode_755_and_the_watcher(self):
        self.conf(); p = self.run_('install'); self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(sorted(os.listdir(self.initd)), ['honey-voice-badger', 'honey-voice-fox'])
        for n in os.listdir(self.initd): self.assertEqual(stat.S_IMODE(os.stat(os.path.join(self.initd, n)).st_mode), 0o755)
        self.assertEqual(rd(os.path.join(self.initd, 'honey-voice-fox')), rd(os.path.join(self.lane, 'openrc', 'honey-voice-fox')))
        self.assertTrue(os.path.isfile(os.path.join(self.engine, 'bin', 'provider-rollout-watcher.py')))

    def test_install_twice_is_unchanged_and_check_then_exits_0(self):
        self.conf(); self.run_('install'); self.assertEqual(self.run_('check').returncode, 0); self.assertNotIn('installed', self.run_('install').stdout)

    def test_a_different_installed_unit_is_backed_up_first(self):
        self.conf(); wr(os.path.join(self.initd, 'honey-voice-fox'), 'old\n'); self.run_('install')
        baks = [n for n in os.listdir(self.initd) if n.startswith('honey-voice-fox.bak-')]
        self.assertEqual(len(baks), 1); self.assertEqual(rd(os.path.join(self.initd, baks[0])), 'old\n')

    def test_dry_run_writes_nothing(self):
        self.conf(); p = self.run_('--dry-run', 'install'); self.assertEqual(p.returncode, 0); self.assertIn('would: backup/install', p.stdout)
        self.assertEqual(os.listdir(self.initd), [])

    def test_it_never_starts_or_enables_anything(self):
        code = '\n'.join(l for l in rd(INSTALL).splitlines() if not l.strip().startswith('#'))
        for needle in ('rc-service', 'rc-update', 'start-stop-daemon', 'systemctl', 'kill'): self.assertNotIn(needle, code, needle)

    @unittest.skipIf(os.geteuid() == 0, 'SKIPPED: runs the installer without a staging directory, which as root would touch the real /etc/init.d')
    def test_without_a_staging_directory_it_needs_root(self):
        self.conf()
        env = dict(os.environ, HONEY_VOICE_ENGINE_ROOT=self.engine, HONEY_VOICE_CONFD_DIR=self.confd); env.pop('HONEY_VOICE_INITD_DIR', None)
        p = subprocess.run(['bash', os.path.join(self.lane, 'openrc', 'honey-voice-install'), 'install'], capture_output=True, text=True, env=env)
        self.assertEqual(p.returncode, 1)
        # the watcher or a unit may only be "requires root" refusals or drift lines, never an install
        self.assertNotIn('installed', p.stdout)


if __name__ == '__main__':
    unittest.main(verbosity=2)
